                    <div class="ssf-inspector-photos"><?php foreach ((array) $record['photos'] as $photo) : if (($photo['question_id'] ?? '') !== $question['id']) { continue; } ?><figure data-photo-id="<?php echo esc_attr($photo['id']); ?>"><img src="<?php echo esc_url($this->photo_url($case['inspection_id'], $photo['id'])); ?>" alt="<?php echo esc_attr($photo['caption'] ?: 'Inspektionsbild'); ?>"><figcaption><input type="text" value="<?php echo esc_attr($photo['caption']); ?>" placeholder="Bildtext" <?php disabled($readonly); ?>><button type="button" data-delete-photo <?php disabled($readonly); ?>>Ta bort</button></figcaption></figure><?php endforeach; ?></div>
