    <section class="ssf-inspector-panel"><h2>Översiktsbilder</h2><p>Rekommenderat men inte blockerande.</p><div class="ssf-inspector-overview-photos"><?php foreach ($template['overview_photos'] as $key => $label) : ?><div class="ssf-inspector-question" data-ssf-question="<?php echo esc_attr($key); ?>"><h3><?php echo esc_html($label); ?></h3><label class="ssf-process-button ssf-process-button--secondary <?php echo $readonly ? 'is-disabled' : ''; ?>">Ta eller välj bild<input class="ssf-inspector-photo-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" <?php disabled($readonly); ?>></label><div class="ssf-inspector-photos"><?php foreach ((array) $record['photos'] as $photo) : if (($photo['question_id'] ?? '') !== $key) { continue; } ?><figure data-photo-id="<?php echo esc_attr($photo['id']); ?>"><img src="<?php echo esc_url($this->photo_url($case['inspection_id'], $photo['id'])); ?>" alt="<?php echo esc_attr($photo['caption'] ?: $label); ?>"><figcaption><input type="text" value="<?php echo esc_attr($photo['caption']); ?>" placeholder="Bildtext" <?php disabled($readonly); ?>><button type="button" data-delete-photo <?php disabled($readonly); ?>>Ta bort</button></figcaption></figure><?php endforeach; ?></div></div><?php endforeach; ?></div></section>

