    <?php if (! $readonly && $case['is_co'] && 'ready_confirmation' === $record['status']) : ?><label class="ssf-inspector-confirm"><input type="checkbox" data-co-confirm> Jag har deltagit i inspektionen och står bakom protokollet.</label><button class="ssf-process-button" type="button" data-workflow="confirm">Bekräfta</button><?php endif; ?>
    <?php if (! $readonly && $case['is_lead'] && 'ready_finalization' === $record['status']) : ?><button class="ssf-process-button" type="button" data-workflow="finalize">Färdigställ och lås protokollet</button><?php endif; ?>
